package com.troy.system.dao.impl;import com.mybatisflex.core.query.QueryCondition;import com.mybatisflex.core.query.QueryWrapper;import com.mybatisflex.core.tenant.TenantManager;import com.troy.common.core.constant.Constants;import com.troy.common.core.enums.DictValueEnums;import com.troy.common.core.utils.StringUtils;import com.troy.common.datasource.service.impl.BaseServiceImpl;import com.troy.system.dao.SysMenuDao;import com.troy.system.entity.SysMenuEntity;import com.troy.system.mapper.SysMenuMapper;import org.springframework.stereotype.Component;import java.util.ArrayList;import java.util.Collection;import java.util.List;import java.util.Set;import static com.troy.system.entity.table.SysMenuEntityTableDef.SYS_MENU_ENTITY;@Componentpublic class SysMenuDaoImpl extends BaseServiceImpl<SysMenuMapper, SysMenuEntity> implements SysMenuDao {    @Override    public List<SysMenuEntity> listAll(String menuName, Long appId) {        return super.dataAuthorityList(                QueryWrapper.create()                        .where(SysMenuEntity::getMenuName).like(StringUtils.escape(menuName), StringUtils.isNotBlank(menuName))                        .and(SysMenuEntity::getAppId).eq(appId)                        .orderBy(SysMenuEntity::getParentId).asc()                        .orderBy(SysMenuEntity::getSort).asc()        );    }    @Override    public List<SysMenuEntity> findChildrenByParentId(List<Long> parentIds) {        return super.list(                QueryWrapper.create()                        .where(SysMenuEntity::getParentId).in(parentIds)                        .orderBy(SysMenuEntity::getParentId).asc()                        .orderBy(SysMenuEntity::getSort).asc()        );    }    @Override    public SysMenuEntity findByMenuCode(String menuCode) {        return super.getOne(                QueryWrapper.create()                        .where(SYS_MENU_ENTITY.MENU_CODE.eq(menuCode).or(SYS_MENU_ENTITY.HREF.eq(menuCode)))        );    }    @Override    public List<SysMenuEntity> findByAppIdOptional(Long appId) {        return super.list(                QueryWrapper.create()                        .where(SYS_MENU_ENTITY.MENU_TYPE.ne(DictValueEnums.BUTTON.getCode()))                        .and(SYS_MENU_ENTITY.IS_BASE.eq(String.valueOf(Constants.ONE)))        );    }    @Override    public SysMenuEntity findMaxSort(Long parentId) {        return super.getOne(                QueryWrapper.create()                        .where(SYS_MENU_ENTITY.PARENT_ID.eq(parentId, StringUtils.isNotNull(parentId)))                        .and(SYS_MENU_ENTITY.PARENT_ID.isNull(StringUtils.isNull(parentId)))                        .and(SYS_MENU_ENTITY.SORT.isNotNull())                        .orderBy(SYS_MENU_ENTITY.SORT.desc()).limit(Constants.ONE)        );    }    @Override    public List<SysMenuEntity> findByAppId(Long appId) {        return super.list(                QueryWrapper.create()                        .where(SYS_MENU_ENTITY.APP_ID.eq(appId))                        .orderBy(SYS_MENU_ENTITY.SORT.asc())        );    }    @Override    public List<SysMenuEntity> findByIdInOptional(Collection<Long> ids) {        QueryCondition queryCondition = QueryCondition.createEmpty();        if (StringUtils.isNotEmpty(ids)) {            QueryCondition queryCondition1 = QueryCondition.createEmpty();            for (Long id : ids) {                queryCondition.or(SYS_MENU_ENTITY.ANCESTORS.like(id));            }            queryCondition.and(SYS_MENU_ENTITY.MENU_TYPE.eq(DictValueEnums.BUTTON.getCode()).and(queryCondition1));        }        return super.list(QueryWrapper.create()                .and((SYS_MENU_ENTITY.APP_ID.isNull()))                .and(SYS_MENU_ENTITY.IS_BASE.eq(String.valueOf(Constants.ONE)))                .and(SYS_MENU_ENTITY.ID.in(ids).or(queryCondition))        );    }    @Override    public void removeAPPIdIn(List<Long> ids) {        super.updateChain().set(SYS_MENU_ENTITY.APP_ID, null).where(SYS_MENU_ENTITY.APP_ID.in(ids)).update();    }    @Override    public void updateAppIdIsNullByAppId(Long appId) {        super.updateChain().set(SYS_MENU_ENTITY.APP_ID, null).where(SYS_MENU_ENTITY.APP_ID.eq(appId)).update();    }    @Override    public List<SysMenuEntity> findByTenantId(Long tenantId) {        List<SysMenuEntity> list = new ArrayList<>();        try {            TenantManager.ignoreTenantCondition();            list = super.list(                    QueryWrapper.create()            );        } finally {            TenantManager.restoreTenantCondition();        }        return list;    }    @Override    public List<SysMenuEntity> findByMenuCodeIn(Set<String> menuCodes) {        return super.list(                QueryWrapper.create()                        .where(SYS_MENU_ENTITY.MENU_CODE.in(menuCodes))        );    }}